extern float vec_distance_xy(void *, void *);

/* index of the nearest of n vectors to a + 0x10 */
int find_nearest_point_index_xy(char *a, char *b, int n) {
    int best = -1;
    int i;
    float m = 32767.0f;
    for (i = 0; i < n; i++) {
        float d = vec_distance_xy(a + 0x10, b + i * 0x10);
        if (d < m) {
            m = d;
            best = i;
        }
    }
    return best;
}
