/* steps a moby's position out of collision and aims it */
void update_moby_movement_with_sphere_collision(char *a, char *b, char *c, float f) {
    int i;
    float v[4];
    char *p = b + 0x10;
    FastVecAdd(p, p, b);
    vec_scale_to_length(p, p, *(float *)(c + 0x1C));
    *(float *)(b + 0x18) = *(float *)(b + 0x18) / *(float *)(b + 0x48);
    FastVecAdd(a + 0x10, a + 0x10, p);
    for (i = 0; i < 6; i++) {
        qcopy(v, a + 0x10);
        v[2] = v[2] + f;
        if (coll_sphere(*(float *)(c + 0x10) * 0.25f, v, 4, a)) {
            qcopy(a + 0x10, eudora_coll_resolved_pos);
            *(float *)(a + 0x18) = *(float *)(a + 0x18) - f;
        } else {
            break;
        }
    }
    *(float *)(a + 0x48) = FastAddRots(fast_atan2(*(float *)(b + 0x10), *(float *)(b + 0x14)), 3.14159265f);
}
